//! WinUI 3 bindings for the controls winio does not wrap.
//!
//! The Windows companion of the Orbit UI loads a Fluent XAML shell
//! ([ADR 0027](../../../docs/design/decisions/0027-windows-fluent-xaml-shell.md))
//! and needs `NavigationView`, `ToggleSwitch`, `NumberBox`, `InfoBar` and their
//! events, none of which `winio-winui3` binds. `bindings.rs` is generated by
//! `tools/parsec-orbit-winui-bindgen` from the Windows App SDK metadata and
//! committed; nothing reads the installed runtime at build time.
//!
//! The types are COM wrappers like those of `winio-winui3`. A value from one
//! crate converts to a type of the other with `Interface::cast`, which goes
//! through the interface id rather than the Rust type.
#![cfg(windows)]
#![allow(
    non_snake_case,
    non_camel_case_types,
    non_upper_case_globals,
    dead_code,
    clippy::all
)]

mod bindings;
pub use bindings::*;
